// Read-only SSH runner for .200. Asserts hostname contains 51.79.226.200.
const { Client } = require("ssh2");
const { PrismaClient } = require("@prisma/client");
require("dotenv").config({ path: "/opt/nxeon/.env" });
const { decryptSecret } = require("/opt/nxeon/lib/crypto-box.ts");

async function getCreds() {
  const p = new PrismaClient();
  const s = await p.server.findUnique({ where: { id: "cmsc9l72y000ghl7iyd87u5ja" }, include: { dedicatedIp: true } });
  await p.$disconnect();
  const pw = decryptSecret(s.rootPasswordEnc);
  return { host: s.dedicatedIp.address, port: 22, password: pw };
}
function run(conn, cmd) {
  return new Promise((resolve, reject) => {
    const c = new Client();
    c.on("ready", () => {
      // guard: assert hostname first, then run
      const guarded = 'ip -4 addr show | grep -q "51.79.226.200" && { ' + cmd + '; } || echo "__HOST_GUARD_FAILED__"';
      c.exec(guarded, (err, stream) => {
        if (err) { c.end(); return reject(err); }
        let out = "", errout = "";
        stream.on("close", () => { c.end(); resolve(out + (errout ? "\n[stderr]\n"+errout : "")); });
        stream.on("data", d => out += d.toString());
        stream.stderr.on("data", d => errout += d.toString());
      });
    });
    c.on("error", reject);
    c.connect({ host: conn.host, port: conn.port, username: "root", password: conn.password, readyTimeout: 15000 });
  });
}
(async () => {
  const conn = await getCreds();
  const cmd = process.argv[2];
  const out = await run(conn, cmd);
  process.stdout.write(out);
})().catch(e => { console.error("ERR:", e.message); process.exit(1); });
