using MongoDB.Bson;
using MongoDB.Bson.Serialization.Attributes;
using SoulPilates.Core.Entities;
using System;

namespace SoulPilates.Core.Entities;

public class Attendance : BaseEntity
{
    /// <summary>
    /// Reference to the <see cref="CalendarSession"/> this attendance belongs to.
    /// May be <c>null</c> for migrated historical attendances (P1-S10 imports
    /// pre-cutover sheet rows without synthesising calendar sessions).
    /// </summary>
    [BsonRepresentation(BsonType.ObjectId)]
    public string? CalendarSessionId { get; set; }

    [BsonRepresentation(BsonType.ObjectId)]
    public string ClientId { get; set; } = null!;

    [BsonRepresentation(BsonType.ObjectId)]
    public string? PackageInstanceId { get; set; }

    public string Status { get; set; } = "BOOKED"; // "RESERVED", "BOOKED", "CHECKED_IN", "NO_SHOW", "LATE_CANCEL", "CANCELLED", "RESCHEDULED"

    public bool IsFreeClass { get; set; } = false;
    public bool CountsTowardsCommission { get; set; } = true;

    public DateTime BookedAt { get; set; } = DateTime.UtcNow;

    /// <summary>
    /// UTC timestamp of when the RESERVED attendance was created. Used by the
    /// <c>ReservationCleanupBackgroundService</c> to expire abandoned reservations.
    /// Null for legacy rows or non-reservation flows (admin walk-ins, etc.);
    /// the cleanup job falls back to <see cref="BookedAt"/> when null.
    /// </summary>
    public DateTime? ReservedAt { get; set; }

    // Booking reference for client confirmation (e.g., SP-260413-4821)
    public string BookingReference { get; set; } = "";

    // Denormalized client info for roster display without joins
    public string? ClientName { get; set; }
    public string? ClientPhone { get; set; }
    public string? ClientEmail { get; set; }

    // Source of booking
    public string BookingSource { get; set; } = "ONLINE"; // "ONLINE", "WALK_IN", "ADMIN"

    // ── Marketing attribution ──
    // Where the booking came from (instagram, facebook, tiktok, google, referral,
    // direct, …). Derived from the customer's answer ("How did you hear about us?")
    // when given, otherwise auto-detected from ad click-ids / UTM tags / referrer at
    // landing. Null on admin/walk-in and legacy rows.
    public string? MarketingSource { get; set; }

    /// <summary>Optional extra detail — the UTM medium/campaign or referrer host, for drill-down.</summary>
    public string? MarketingDetail { get; set; }

    // ── Customer Booking Portal — Enriched Booking Data ──
    public string? Goals { get; set; }                           // Client's goals for this session
    public string? EquipmentType { get; set; }                   // For private classes
    public string? PaymentMethod { get; set; }                   // "PACKAGE_CREDIT", "STRIPE_DEPOSIT", "STRIPE_FULL", "PAY_AT_STUDIO"
    public string? StripePaymentIntentId { get; set; }           // Stripe PaymentIntent reference
    public decimal? AmountPaid { get; set; }                     // Amount paid online
    public decimal? AmountDueAtStudio { get; set; }              // Remaining balance for studio collection

    /// <summary>
    /// Number of seats this attendance row represents. Group-class only —
    /// private classes are always 1. Defaults to 1 so legacy rows deserialise unchanged.
    /// <para>
    /// The studio deducts <c>Quantity</c> credits on check-in (or marks
    /// <c>Quantity × SessionFee</c> for Pay-at-Studio). <see cref="CalendarSession.CurrentBookings"/>
    /// is incremented by this number when the reservation is created.
    /// </para>
    /// </summary>
    public int Quantity { get; set; } = 1;

    // ━━ P3-S08 — Reminder idempotency ━━
    /// <summary>
    /// Idempotency tags for the reminder background job. Holds short
    /// window-identifiers such as <c>"24h"</c> and <c>"1h"</c>.
    /// <see cref="SoulPilates.Services.ReminderService"/> inspects this
    /// list before sending and appends the matching tag after the
    /// email dispatch succeeds, so the next hourly tick can skip
    /// already-notified attendances. Missing-field BSON deserialisation
    /// reads as an empty list, so historical attendances need no
    /// migration.
    /// </summary>
    public List<string> RemindersSent { get; set; } = new();

    // ━━ Late Reschedule Tracking ━━
    /// <summary>
    /// When this attendance was created via a late reschedule, this links back
    /// to the original attendance that was rescheduled. Null for fresh bookings.
    /// </summary>
    [BsonRepresentation(BsonType.ObjectId)]
    public string? RescheduledFromAttendanceId { get; set; }

    /// <summary>
    /// Set to <c>true</c> when this attendance has been rescheduled to another
    /// session. The original attendance is marked <c>RESCHEDULED</c> status and
    /// this flag is set so the BOOKING-mode limit can fast-check without scanning.
    /// </summary>
    public bool HasBeenRescheduled { get; set; } = false;

    /// <summary>
    /// Partner referral discount percentage applied at checkout time
    /// (e.g. <c>0.10m</c> = 10% off). When set, the payroll service
    /// calculates the instructor's commission on
    /// <c>session.DropInPrice × (1 − ReferralDiscountPct)</c> instead of
    /// the full blueprint price, so the referral reduction is always
    /// deducted before the commission percentage is applied.
    /// <para>
    /// <c>null</c> means no partner referral was applied; historical rows
    /// that pre-date this field deserialise as <c>null</c> and are treated
    /// as zero-discount — guaranteeing backward-compatible payroll re-runs.
    /// </para>
    /// </summary>
    public decimal? ReferralDiscountPct { get; set; }

    /// <summary>
    /// Actual instructor commission for this class as recorded in the studio's
    /// historical spreadsheet import. When set, payroll uses THIS amount verbatim
    /// instead of recomputing base × rate — the imported rates were manually
    /// negotiated per month (not a class-count tier) and the base already reflects
    /// discounts and package fractional value, so recomputation cannot reproduce
    /// them. <c>null</c> for classes booked in-app (which compute normally).
    /// </summary>
    public decimal? ImportedCommissionAmount { get; set; }

    /// <summary>
    /// Actual per-class revenue (commission base) for this class from the
    /// spreadsheet import — the real discounted / package-fractional value, not
    /// the drop-in price. Used by the class-detail panel and any imported
    /// commission display. <c>null</c> for in-app bookings.
    /// </summary>
    public decimal? ImportedClassRevenue { get; set; }

    /// <summary>
    /// Promotion applied to this booking at checkout (customer-entered code or an
    /// auto-attached offer like the first-time "bring a friend"). Null when no
    /// promo was used. <see cref="PromoCode"/> is the human code for reporting;
    /// <see cref="PromotionId"/> links the <c>Promotion</c> that was redeemed.
    /// </summary>
    public string? PromoCode { get; set; }

    [MongoDB.Bson.Serialization.Attributes.BsonRepresentation(MongoDB.Bson.BsonType.ObjectId)]
