using MongoDB.Bson;
using MongoDB.Bson.Serialization.Attributes;
using System.Collections.Generic;

namespace SoulPilates.Core.Entities;

/// <summary>
/// Per-staff, per-month override of the commission rate sheet.
/// When a row exists for a given StaffId/Year/Month,
/// <see cref="SoulPilates.Services.PayrollService"/> uses these values
/// instead of the <see cref="StaffRateRevision"/> that would normally
/// be in force for that period.
///
/// <para>
/// Use case: Nhi earned 25%/30%/35% tiered rates in months prior to the
/// current configuration. Rather than creating a new StaffRateRevision
/// (which affects ALL months from that date forward via the as-of query),
/// an override pins the exact tiers for a single month without disturbing
/// past or future payroll runs.
/// </para>
///
/// <para>
/// The resolution order in PayrollService is:
///   1. MonthlyCommissionOverride for (StaffId, Year, Month) — highest priority.
///   2. StaffRateRevision as-of period end — normal path.
///   3. Live Staff document — legacy fallback.
/// </para>
/// </summary>
public class MonthlyCommissionOverride : BaseEntity
{
    /// <summary>Foreign key into the Staff collection.</summary>
    [BsonRepresentation(BsonType.ObjectId)]
    public string StaffId { get; set; } = null!;

    /// <summary>
    /// Denormalised name so the override survives a rename of the staff member.
    /// </summary>
    public string StaffNameSnapshot { get; set; } = string.Empty;

    /// <summary>Calendar year (e.g. 2025).</summary>
    public int Year { get; set; }

    /// <summary>Calendar month 1–12.</summary>
    public int Month { get; set; }

    /// <summary>Free-text rationale (e.g. "Pre-May contract: 25/30/35 tiers").</summary>
    public string Note { get; set; } = string.Empty;

    // ── Commission rate snapshot — mirrors StaffRateRevision ─────────────

    public string CommissionModel { get; set; } = "PERCENTAGE_TIERED";

    /// <summary>Tiered private-class commission ladder for this month.</summary>
    public List<CommissionTier> Tiers { get; set; } = new();

    public bool HasTieredPrivateCommission { get; set; } = true;
    public decimal FlatPrivateCommissionPct { get; set; } = 0m;

    public decimal GroupFlatRatePerClass { get; set; }
    public decimal GroupRatePerHead { get; set; }

    public decimal FreeGroupClassRate { get; set; }
    public decimal FreePrivateClassRate { get; set; }

    public decimal RatePerHead { get; set; }
    public List<HeadcountPayoutTier> HeadcountTiers { get; set; } = new();
    public decimal PrivateRatePerHead { get; set; }
    public List<HeadcountPayoutTier> PrivateHeadcountTiers { get; set; } = new();
    public bool UseMarginalHeadcountTiers { get; set; } = true;

    public decimal BaseSalary { get; set; }
    public decimal BaseRate { get; set; }
}
