using MongoDB.Bson;
using MongoDB.Bson.Serialization.Attributes;
using SoulPilates.Core.Entities;

namespace SoulPilates.Core.Entities;

public class InvoiceLine : BaseEntity
{
    [BsonRepresentation(BsonType.ObjectId)]
    public string InvoiceId { get; set; } = null!;

    [BsonRepresentation(BsonType.ObjectId)]
    public string ProductId { get; set; } = null!;

    [BsonRepresentation(BsonType.ObjectId)]
    public string? VariantId { get; set; }

    public int Quantity { get; set; }
    public decimal UnitPrice { get; set; }
    public decimal LineDiscount { get; set; }
    public decimal LineTotal { get; set; }

    /// <summary>
    /// Links this invoice line to a specific booking (Attendance) when the
    /// line represents a class drop-in purchased at POS or a studio-collected
    /// balance. Null for merchandise, packages, and non-class lines.
    /// </summary>
    [BsonRepresentation(BsonType.ObjectId)]
    public string? AttendanceId { get; set; }

    /// <summary>
    /// Links this invoice line to a specific calendar session when the
    /// line represents a class drop-in. Null for non-class lines.
    /// </summary>
    [BsonRepresentation(BsonType.ObjectId)]
    public string? CalendarSessionId { get; set; }

    /// <summary>
    /// Optional human-readable description for the line (e.g. "Group Class Session").
    /// When set, InvoiceService uses this instead of looking up the product name.
    /// Used for credit-based class bookings where ProductId is a blueprint ID.
    /// </summary>
    public string? Description { get; set; }

    /// Snapshot of <see cref="Product.Type"/> at the moment the invoice was created. Used by the
    /// washout pipeline to attribute revenue to the correct category ("PACKAGE", "MERCHANDISE",
    /// etc.) <em>as it was at sale time</em> — so a later reclassification of the product
    /// (e.g. switching it from PACKAGE to MERCHANDISE) cannot retroactively reshuffle historical
    /// <c>MonthlyWashout.RevenueByCategory</c> totals. Null on lines that pre-date this field;
    /// the washout reader falls back to the live <c>Product.Type</c> in that case.
    /// </summary>
    public string? ProductTypeSnapshot { get; set; }
}

}

