public async Task<IActionResult> GetSessionsForBlueprint(string blueprintId)
{
    var now = DateTime.UtcNow;
    var sessions = await _schedulingService.GetSessionsAsync(now, now.AddDays(14));
    var matching = sessions
        .Where(s => s.ClassBlueprintId == blueprintId
            && s.Status == "SCHEDULED"
            && string.IsNullOrWhiteSpace(s.BlockedReason))
        .OrderBy(s => s.StartTime)
        .Take(30)
        .Select(s => new
        {
            id = s.Id,
            className = s.ClassName,
            instructorName = s.InstructorName,
            startTime = s.StartTime,
            endTime = s.EndTime,
            format = s.Format,
            capacity = s.Capacity,
            currentBookings = s.CurrentBookings,
            spotsLeft = Math.Max(0, s.Capacity - s.CurrentBookings),
            dropInPrice = s.DropInPrice ?? 0m,
        })
        .ToList();
    return Ok(matching);
}

