    // ━━ Void Invoice ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

    public async Task<bool> VoidInvoiceAsync(string invoiceId, string reason)
    {
        var invoice = await _invoices.Find(i => i.Id == invoiceId).FirstOrDefaultAsync();
        if (invoice == null) return false;
        if (invoice.Status == "VOIDED") return true; // already voided

        var update = Builders<Invoice>.Update
            .Set(i => i.Status, "VOIDED")
            .Set(i => i.Notes, $"[VOIDED] {reason}" + (string.IsNullOrWhiteSpace(invoice.Notes) ? "" : $"\n\nOriginal notes: {invoice.Notes}"));

        var result = await _invoices.UpdateOneAsync(i => i.Id == invoiceId, update);
        if (result.ModifiedCount > 0)
        {
            // Voiding cancels the sale, so its payments must stop counting as
            // revenue (the dashboard + P&L sum Payment records). The audit trail —
            // the original PAYMENT_RECEIVED events plus this VOID — preserves the
            // history, so removing the payment docs is a clean revenue reversal.
            var voidedPayments = await _payments.Find(p => p.InvoiceId == invoiceId).ToListAsync();
            var voidedTotal = voidedPayments.Sum(p => p.AmountPaid);
            var removedPayments = await _payments.DeleteManyAsync(p => p.InvoiceId == invoiceId);

            // Pull the voided revenue back out of the client's lifetime value (VIP driver).
            if (!string.IsNullOrWhiteSpace(invoice.ClientId) && voidedTotal != 0)
                await _clients.UpdateOneAsync(c => c.Id == invoice.ClientId,
                    Builders<Client>.Update.Inc(c => c.LifetimeValue, -voidedTotal));

            await _audit.LogAsync(
                action: "VOID",
                entityType: "Invoice",
                entityId: invoiceId,
                entityLabel: invoice.InvoiceNumber,
                after: new { reason, previousStatus = invoice.Status, removedPayments = removedPayments.DeletedCount });
        }
        return result.ModifiedCount > 0;
    }

    // ━━ Refund Invoice ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

    public async Task<object> RefundInvoiceAsync(string invoiceId, decimal amount, string refundMethod, string reason)
    {
        if (amount <= 0)
            throw new InvalidOperationException("Refund amount must be greater than zero.");

        var invoice = await _invoices.Find(i => i.Id == invoiceId).FirstOrDefaultAsync()
            ?? throw new InvalidOperationException("Invoice not found.");

        if (invoice.Status == "VOIDED")
            throw new InvalidOperationException("Cannot refund a voided invoice.");

        // Check how much has been paid
        var allPayments = await _payments.Find(p => p.InvoiceId == invoiceId).ToListAsync();
        var totalPaid = allPayments.Sum(p => p.AmountPaid);

        if (amount > totalPaid)
            throw new InvalidOperationException($"Refund amount ({amount:N0}) exceeds total paid ({totalPaid:N0}).");

        // Create a negative "refund" payment entry
        var refundPayment = new Payment
        {
            InvoiceId = invoiceId,
            AmountPaid = -amount,
            PaymentDate = DateTime.UtcNow,
            PaymentMethod = refundMethod,
        };
        await _payments.InsertOneAsync(refundPayment);

        // Pull the refunded amount back out of the client's lifetime value (VIP driver).
        if (!string.IsNullOrWhiteSpace(invoice.ClientId) && amount != 0)
            await _clients.UpdateOneAsync(c => c.Id == invoice.ClientId,
                Builders<Client>.Update.Inc(c => c.LifetimeValue, -amount));

        // Recalculate
        var newTotalPaid = totalPaid - amount;
        string newStatus;
        if (newTotalPaid <= 0)
            newStatus = "REFUNDED";
        else if (newTotalPaid >= invoice.TotalNet)
            newStatus = "PAID";
        else
            newStatus = "PARTIAL";

        var noteSuffix = $"\n[REFUND] {amount:N0} ₫ via {refundMethod}: {reason}";
        var update = Builders<Invoice>.Update
            .Set(i => i.Status, newStatus)
            .Set(i => i.Notes, (invoice.Notes ?? "") + noteSuffix);
        await _invoices.UpdateOneAsync(i => i.Id == invoiceId, update);

        await _audit.LogAsync(
            action: "REFUND",
            entityType: "Invoice",
            entityId: invoiceId,
            entityLabel: invoice.InvoiceNumber,
            after: new { amount, refundMethod, reason, previousStatus = invoice.Status, newStatus });

        return new
        {
            refundedAmount = amount,
            newTotalPaid = newTotalPaid,
            newStatus,
            refundPaymentId = refundPayment.Id,
        };
    }
}

############ CollectStudioPaymentAsync (1106-1300) ############
    public async Task<object> CollectStudioPaymentAsync(
        string attendanceId, decimal amount, string paymentMethod,
        string? notes, IInvoiceService invoiceService, int? attendingSeats = null,
        IReadOnlyList<PaymentSplitLine>? paymentSplits = null)
    {
        // SPM-124 — PACKAGE_CREDIT settles the booking against the client's prepaid
        // wallet, so amount is irrelevant (no money changes hands). Only the cash /
        // monetary paths require a positive amount.
        var isCredit = string.Equals(paymentMethod, "PACKAGE_CREDIT", StringComparison.OrdinalIgnoreCase);

        if (!isCredit && amount <= 0)
            throw new InvalidOperationException("Amount must be greater than zero.");

        var attendance = await _attendances.Find(a => a.Id == attendanceId).FirstOrDefaultAsync()
            ?? throw new InvalidOperationException("Booking not found.");

        // SPM-79 — A booking that was rescheduled away (or fully cancelled) is locked:
        // its seat/payment lives on the new booking (RESCHEDULED) or was voided with no
        // penalty (CANCELLED), so it can no longer take a payment.
        // NOTE: LATE_CANCEL is intentionally NOT locked — a late cancellation is a
        // penalty state, so the studio can still charge the late-cancel fee or deduct a
        // package credit per policy (a package client forfeits one credit).
        if (attendance.Status == "RESCHEDULED" || attendance.Status == "CANCELLED")
            throw new BusinessRuleException("BOOKING.NOT_COLLECTABLE",
                "This booking was rescheduled or cancelled and can no longer take a payment.");

        if (attendance.IsFreeClass)
            throw new InvalidOperationException("Cannot collect payment for a free class.");

        CalendarSession? session = null;
        if (!string.IsNullOrWhiteSpace(attendance.CalendarSessionId))
            session = await _sessions.Find(s => s.Id == attendance.CalendarSessionId).FirstOrDefaultAsync();

        // Partial attendance: when fewer people showed up than were booked (e.g. a
        // 3-seat booking where 2 arrived), the staff check in / charge only the
        // attendees. Shrink the booking to that count and release the no-show seat(s)
        // back to the class BEFORE settling, so both the credits deducted and the
        // money charged reflect who actually came.
        if (attendingSeats is int attend)
        {
            var booked = Math.Max(1, attendance.Quantity);
            if (attend < 1 || attend > booked)
                throw new BusinessRuleException("BOOKING.INVALID_ATTENDING",
                    $"Attending count must be between 1 and {booked}.");
            if (attend < booked)
            {
                // Re-base the outstanding balance to the attendee count so the
                // no-show seat(s) don't leave a phantom balance behind. The drop-in
                // path below then clears this with the payment; the credit path
                // zeroes it on settle.
                var newDue = (session?.DropInPrice ?? 0m) * attend;
                await _attendances.UpdateOneAsync(a => a.Id == attendance.Id,
                    Builders<Attendance>.Update
                        .Set(a => a.Quantity, attend)
                        .Set(a => a.AmountDueAtStudio, newDue));
                attendance.Quantity = attend;
                attendance.AmountDueAtStudio = newDue;
                if (!string.IsNullOrWhiteSpace(attendance.CalendarSessionId))
                    await ReleaseSessionCapacityAsync(attendance.CalendarSessionId, booked - attend);
            }
        }

        // SPM-124 — Settle via package credit. Mirrors WalkInCheckoutAsync's credit
        // mechanics: resolve a usable wallet for the session format (ACTIVE +
        // LOW_BALANCE), deduct one credit per booked seat, stamp the attendance as
        // fully paid by credit, and write a 0đ PAID invoice for the audit trail.
        // CAUTION: this debits REAL prepaid credits from the client's wallet.
        if (isCredit)
            return await SettleBookingWithCreditAsync(attendance, session, invoiceService);

        // Determine the expected amount from the session's snapshotted drop-in price,
        // multiplied by the number of seats this booking covers (a "book for 2"
        // party is one attendance with Quantity = 2). If the staff enters a
        // different amount, a note/reason is required.
        var seats = Math.Max(1, attendance.Quantity);
        var expectedAmount = (session?.DropInPrice ?? 0m) * seats;
        var previouslyPaid = attendance.AmountPaid ?? 0m;
        var remainingDue = expectedAmount > 0
            ? Math.Max(0, expectedAmount - previouslyPaid)
            : (attendance.AmountDueAtStudio ?? 0m);

        // If custom amount differs from remaining due and no reason given, reject.
        if (remainingDue > 0 && amount != remainingDue && string.IsNullOrWhiteSpace(notes))
            throw new InvalidOperationException(
                $"Amount ({amount:N0}) differs from expected ({remainingDue:N0}). A note/reason is required for custom amounts.");

        // ── Resolve the tender lines ──────────────────────────────────────────
        // A split payment (part cash + part card, …) is recorded as several
        // Payment ledger rows — one per {method, amount} — validated to sum to
        // the collected `amount`, so each income stream is credited its real
        // share and the analytics payment-method distribution stays accurate.
        // With no split supplied the whole amount is one row via `paymentMethod`,
        // byte-for-byte the original single-method behaviour (back-compat).
        List<PaymentSplitLine> tenders;
        if (paymentSplits != null && paymentSplits.Count > 0)
        {
            try
            {
                tenders = PaymentSplit.Validate(paymentSplits, amount);
            }
            catch (ArgumentException ex)
            {
                throw new InvalidOperationException(ex.Message);
            }
        }
        else
        {
            tenders = new List<PaymentSplitLine>
            {
                new PaymentSplitLine
                {
                    Method = string.IsNullOrWhiteSpace(paymentMethod) ? "CASH" : paymentMethod,
                    Amount = amount,
                },
            };
        }

        // ── Check for existing linked invoice (e.g. from online partial payment) ──
        // If an invoice already exists for this attendance (created by STRIPE_DEPOSIT),
        // add the payment to it rather than creating a new one.
        var existingInvoice = await _invoices.Find(
            Builders<Invoice>.Filter.ElemMatch(
                i => i.Lines,
                Builders<InvoiceLine>.Filter.Eq(l => l.AttendanceId, attendanceId)
            )
        ).FirstOrDefaultAsync();

        string? invoiceId;
        string? invoiceNumber;

        if (existingInvoice != null && existingInvoice.Status != "PAID" && existingInvoice.Status != "VOIDED")
        {
            // Add payment to existing invoice (partial → paid) — one ledger row
            // per tender line so a split credits each income stream separately.
            invoiceId = existingInvoice.Id;
            invoiceNumber = existingInvoice.InvoiceNumber;

            foreach (var t in tenders)
            {
                await invoiceService.AddPaymentAsync(existingInvoice.Id!, new Payment
                {
                    AmountPaid = t.Amount,
                    PaymentDate = DateTime.UtcNow,
                    PaymentMethod = t.Method,
                });
            }
        }
        else
        {
            // No existing invoice — create a new one (PAY_AT_STUDIO flow or admin-added booking)
            var invoiceNotes = string.IsNullOrWhiteSpace(notes)
                ? $"Studio collection for {session?.ClassName ?? "class"} on {(session == null ? "N/A" : StudioTime.Local(session.StartTime).ToString("yyyy-MM-dd"))}"
                : notes;

            var invoice = new Invoice
            {
                ClientId = attendance.ClientId,
                TotalDiscount = 0m,
                TotalTax = 0m,
                IssueDate = DateTime.UtcNow,
                Notes = invoiceNotes,
                Lines = new List<InvoiceLine>
                {
                    new InvoiceLine
                    {
                        ProductId = session?.ClassBlueprintId ?? string.Empty,
                        Description = ClassFormatLabel(session?.Format),
                        Quantity = Math.Max(1, attendance.Quantity),
                        UnitPrice = amount / Math.Max(1, attendance.Quantity),
                        LineDiscount = 0m,
                        AttendanceId = attendanceId,
                        CalendarSessionId = attendance.CalendarSessionId,
                        ProductTypeSnapshot = "CLASS",
                    }
                }
            };

            var created = await invoiceService.CreateInvoiceAsync(invoice);
            invoiceId = created.Id;
            invoiceNumber = created.InvoiceNumber;

            // Add the full payment immediately — one ledger row per tender line so
            // a split payment credits each income stream its real share.
            foreach (var t in tenders)
            {
                await invoiceService.AddPaymentAsync(created.Id!, new Payment
                {
                    AmountPaid = t.Amount,
                    PaymentDate = DateTime.UtcNow,
                    PaymentMethod = t.Method,
                });
            }
        }

        // Update the Attendance's payment tracking fields atomically

############ CollectStudioPaymentAsync tail (1300-1400) ############
        // Update the Attendance's payment tracking fields atomically
        var newAmountPaid = previouslyPaid + amount;
        var newAmountDue = Math.Max(0, (attendance.AmountDueAtStudio ?? remainingDue) - amount);

        var attUpdate = Builders<Attendance>.Update
            .Set(a => a.AmountPaid, newAmountPaid)
            .Set(a => a.AmountDueAtStudio, newAmountDue);

        // If no payment method was set (walk-in admin booking), stamp it now
        if (string.IsNullOrWhiteSpace(attendance.PaymentMethod))
            attUpdate = attUpdate.Set(a => a.PaymentMethod, "PAY_AT_STUDIO");

        await _attendances.UpdateOneAsync(a => a.Id == attendanceId, attUpdate);

        // BOGO ("Buy 1 Get 1 Free") reward — issue the free class credit only once
        // the first class is actually PAID (balance cleared here at the studio).
        if (newAmountDue <= 0m)
        {
            attendance.AmountDueAtStudio = newAmountDue; // keep local copy consistent
            await GrantBogoCreditIfEligibleAsync(attendance);
        }

        return new
        {
            invoiceId,
            invoiceNumber,
            amountCollected = amount,
            totalPaid = newAmountPaid,
            remainingDue = newAmountDue,
            paymentMethod,
        };
    }

    /// <summary>
    /// BOGO reward grant (studio-payment path). Mirrors the Stripe-path grant in
    /// PaymentService: one free GROUP credit (7-day expiry, value 0), idempotent via
