############ AdminAddStudentAsync (2466-2600) ############
    public async Task<Attendance> AdminAddStudentAsync(string sessionId, string clientId, string clientName, string? clientPhone, int quantity = 1)
    {
        var session = await _sessions.Find(s => s.Id == sessionId).FirstOrDefaultAsync();
        if (session == null) throw new NotFoundException("BOOKING.SESSION_NOT_FOUND", "Session not found.");

        // SPM-126 — The duplicate-booking guard is intentionally omitted here.
        // The owner wants admins to add the same client to a session more than once
        // (e.g. the client is bringing a guest, or buying a second seat at the desk).
        // Each add is a distinct Attendance row and bumps CurrentBookings by the seat
        // quantity. This mirrors WalkInCheckoutAsync, which by design also skips the
        // guard. The customer-facing BookClientAsync guard is unaffected.

        // Capacity guard — enforce even for admin adds. Accounts for the requested
        // quantity so a 2-seat add against 1 remaining spot is rejected.
        var requestedSeats = Math.Max(1, quantity);
        if (string.Equals(session.Format, "PRIVATE", StringComparison.OrdinalIgnoreCase))
        {
            // SPM-98 — Duo private. A PRIVATE session is created with Capacity=1 (a
            // 1-on-1 slot). The studio may instead run it as a DUO — two clients in
            // the same private session. Mirror ReserveSpotAsync's duo rule for the
            // admin/desk add path: clamp any private add to at most 2 seats, ensure
            // the class stays within the duo cap of 2 total, then lift the session's
            // Capacity 1→2 so the second seat (one booker taking ×2, OR a distinct
            // second client taking ×1) fits the atomic capacity guard below. Only ever
            // raise it — never shrink an admin-configured larger capacity.
            requestedSeats = Math.Min(requestedSeats, 2);
            var wouldHold = session.CurrentBookings + requestedSeats;
            if (wouldHold > 2)
                throw new BusinessRuleException("BOOKING.PRIVATE_DUO_MAX",
                    "A private session can hold at most 2 people (duo). Remove a seat before adding another.");
            if (session.Capacity < wouldHold)
            {
                await _sessions.UpdateOneAsync(
                    s => s.Id == sessionId,
                    Builders<CalendarSession>.Update.Set(s => s.Capacity, 2));
                session.Capacity = 2;
            }
        }
        var spotsLeft = session.Capacity - session.CurrentBookings;
        if (spotsLeft <= 0)
            throw new BusinessRuleException("BOOKING.CAPACITY_REACHED", "This class is at full capacity.");
        if (requestedSeats > spotsLeft)
            throw new BusinessRuleException("BOOKING.CAPACITY_REACHED",
                $"Only {spotsLeft} spot{(spotsLeft == 1 ? "" : "s")} remaining. Cannot add {requestedSeats} seat{(requestedSeats == 1 ? "" : "s")}.");

        // SPM-120 — A manual admin/instructor add is an UNPAID booking that the studio
        // must collect for at the desk. Mirror the WalkInCheckout snapshot logic so the
        // POS "collect" card surfaces the correct outstanding balance instead of ₫0:
        // stamp PaymentMethod = PAY_AT_STUDIO and snapshot the amount due from the
        // session's drop-in price × seat quantity (defaults to 1). For a free class
        // (DropInPrice 0 or null) the due stays 0 so nothing is collected.
        // No invoice is created here — CollectStudioPaymentAsync creates and links one
        // at collect time via InvoiceLine.AttendanceId.
        var amountDue = (session.DropInPrice ?? 0m) * requestedSeats;

        var attendance = new Attendance
        {
            CalendarSessionId = sessionId,
            ClientId = clientId,
            Status = "BOOKED",
            BookedAt = DateTime.UtcNow,
            BookingReference = GenerateBookingReference(),
            ClientName = clientName,
            ClientPhone = clientPhone,
            BookingSource = "WALK_IN",
            PaymentMethod = "PAY_AT_STUDIO",
            AmountPaid = null,
            AmountDueAtStudio = amountDue,
            Quantity = requestedSeats,
        };
        // Atomically claim the seat(s) before persisting so concurrent adds/bookings can't overbook.
        if (!await TryClaimSessionCapacityAsync(sessionId, requestedSeats))
            throw new BusinessRuleException("BOOKING.CAPACITY_REACHED", "This class is at full capacity.");
        try
        {
            await _attendances.InsertOneAsync(attendance);
        }
        catch
        {
            await ReleaseSessionCapacityAsync(sessionId, requestedSeats);
            throw;
        }

        // P5-PWA — a manual desk booking (admin / receptionist / instructor add)
        // is a real booking too, so fire the same "New booking" push the customer
        // self-service path fires. Fire-and-forget: never fails the booking.
        // A genuine desk booking ends the client's lapse — clear the win-back throttle.
        await ClearWinBackThrottleAsync(clientId);
        FireAndForgetManualBookingPush(attendance, session);
        // Manual booking confirmation email (board: "Manual booking confirmation email").
        FireAndForgetManualBookingEmail(attendance, session);

        return attendance;
    }

