############ CreateManualSessionAsync (3781-3870) ############
    public async Task<CalendarSession> CreateManualSessionAsync(CalendarSession session)
    {
        session.Origin = "MANUAL";
        session.CreatedAt = DateTime.UtcNow;

        // A manual session must inherit its BASE / general settings from the parent
        // blueprint so it can never drift from it (owner decision): only the SCHEDULE
        // — StartTime/EndTime/Capacity and the chosen instructor — comes from the
        // request; every general field (name, focus, difficulty, format, equipment,
        // image, tags, drop-in price, freelance flag, public-visibility default) is
        // copied from the blueprint, mirroring MaterialiseBlueprintInternal so a
        // manual session is indistinguishable from a materialised one.
        if (!string.IsNullOrWhiteSpace(session.ClassBlueprintId))
        {
            var bp = await _blueprints.Find(b => b.Id == session.ClassBlueprintId).FirstOrDefaultAsync();
            if (bp != null)
            {
                session.ClassName       = bp.ClassName;
                session.FocusArea       = bp.FocusArea;
                session.DifficultyLevel = bp.DifficultyLevel;
                session.Format          = bp.Format;

                // SPM-71 — denormalise the full equipment list; keep the legacy
                // singular = first entry for back-compat (treats old singular as [singular]).
                var equipmentTypes      = ResolveEquipmentTypes(bp);
                session.EquipmentTypes  = equipmentTypes;
                session.EquipmentType   = equipmentTypes.Count > 0 ? equipmentTypes[0] : bp.EquipmentType;

                session.ImageUrl        = bp.ImageUrl;
                session.Tags            = bp.Tags ?? new List<string>();
                session.DropInPrice     = bp.DropInPrice;
                session.IsFreelance     = bp.IsFreelance;
                // SPM-91 — visibility default comes from the blueprint; admins can flip
                // an individual session via the Edit Session modal afterwards.
                session.IsPublic        = bp.DefaultIsPublic;

                // Schedule-specific: keep the request's capacity, falling back to the
                // blueprint default when none was supplied.
                if (session.Capacity <= 0) session.Capacity = bp.DefaultCapacity;

                // Instructor: keep the chosen one; fall back to the blueprint default.
                if (string.IsNullOrWhiteSpace(session.InstructorId))
                {
                    // SPM-122 — InstructorId is [BsonRepresentation(ObjectId)]: coerce
                    // empty/whitespace to NULL (not "") to avoid a BsonSerializationException
                    // when the blueprint has no default instructor.
                    session.InstructorId   = string.IsNullOrWhiteSpace(bp.DefaultInstructorId)
                        ? null : bp.DefaultInstructorId;
                    session.InstructorName = bp.DefaultInstructorName ?? session.InstructorName;
                }
                // The manual form doesn't send the instructor photo — resolve it (and
                // the name, if missing) so the public booking card renders correctly.
                if (!string.IsNullOrWhiteSpace(session.InstructorId) &&
                    string.IsNullOrWhiteSpace(session.InstructorPhotoUrl))
                {
                    var staff = await _staff.Find(s => s.Id == session.InstructorId).FirstOrDefaultAsync();
                    session.InstructorPhotoUrl = staff?.PhotoUrl;
                    if (string.IsNullOrWhiteSpace(session.InstructorName))
                        session.InstructorName = staff?.Name ?? session.InstructorName;
                }
            }
        }

        await PopulateFreelanceSessionMetadataAsync(session);

        // SPM-70 — reject a class that would overlap an existing block.
        await EnsureNoBlockConflictForClassAsync(session);
        await _sessions.InsertOneAsync(session);
        return session;
    }

    public async Task<bool> OverrideSessionAsync(string sessionId, CalendarSession updated, string? note)
    {
