namespace SoulPilates.Core.Entities;

/// <summary>
/// One-off ad-hoc payout: e.g. Nhi 250K for handling extra clients in a month,
/// Phong 300K for filming a video, Santino 1M end-of-quarter performance bonus.
/// Aggregated by the washout's <c>ApplyBonusesAsync</c> pass into either
/// <c>OwnerDistribution.BonusAmount</c> (for owner recipients) or
/// <c>StaffPayable.BonusAmount</c> (for non-owner recipients).
/// <para>
/// <c>RecipientStaffName</c> is denormalised intentionally — supports legacy
/// staff who don't have a <c>Staff</c> row yet, and free-text recipients for
/// imported / one-off payouts.
/// </para>
/// </summary>
public class Bonus : BaseEntity
{
    /// <summary>Optional FK; populated when the recipient has a Staff row.</summary>
    public string? RecipientStaffId { get; set; }

    /// <summary>Always populated — denormalised for legacy / free-text recipients.</summary>
    public string RecipientStaffName { get; set; } = null!;

    public int Year { get; set; }
    public int Month { get; set; }
    public decimal Amount { get; set; }

    /// <summary>Free-text rationale ("End-of-quarter performance", "Filming May 2026").</summary>
    public string? Reason { get; set; }

    public string AuthorisedByUserId { get; set; } = null!;
    public DateTime AuthorisedAt { get; set; } = DateTime.UtcNow;

    public string PaidStatus { get; set; } = "PENDING"; // "PENDING" | "PAID"
    public DateTime? PaidAt { get; set; }
}
